[{"id":"369bff6b","elType":"container","settings":[],"elements":[{"id":"1f239993","elType":"widget","settings":{"editor":"<section class="rt-pacs-page">
  <style>
    .rt-pacs-page,
    .rt-pacs-page * {
      box-sizing: border-box;
    }

    .rt-pacs-page {
      --rt-bg: #061423;
      --rt-bg-2: #0a1d31;
      --rt-bg-3: #102844;
      --rt-card: #0d2138;
      --rt-card-2: #132c48;
      --rt-white: #ffffff;
      --rt-text: #eaf1f8;
      --rt-muted: #b8c6d8;
      --rt-orange: #f09a37;
      --rt-orange-2: #ffb65c;
      --rt-orange-dark: #cf7f22;
      --rt-line: rgba(255, 255, 255, 0.09);
      --rt-shadow: 0 28px 80px rgba(0, 0, 0, 0.34);
      --rt-glow: 0 0 46px rgba(240, 154, 55, 0.18);
      position: relative;
      overflow-x: hidden;
      overflow-y: visible;
      color: var(--rt-text);
      background:
        radial-gradient(circle at 82% 12%, rgba(240, 154, 55, 0.13), transparent 26%),
        radial-gradient(circle at 14% 18%, rgba(255, 255, 255, 0.045), transparent 28%),
        linear-gradient(135deg, #04111d 0%, #07192b 48%, #091c2f 100%);
      font-family: inherit;
    }

    .rt-pacs-page::before {
      content: "";
      position: fixed;
      inset: 0;
      z-index: 0;
      pointer-events: none;
      background:
        linear-gradient(rgba(255, 255, 255, 0.026) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.026) 1px, transparent 1px);
      background-size: 42px 42px;
      mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.82), rgba(0, 0, 0, 0.12));
    }

    .rt-pacs-page > * {
      position: relative;
      z-index: 1;
    }

    .rt-pacs-page a {
      color: inherit;
      text-decoration: none;
    }

    .rtp-wrap {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
    }

    .rtp-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 8px 14px;
      border-radius: 999px;
      border: 1px solid rgba(240, 154, 55, 0.28);
      background: rgba(240, 154, 55, 0.12);
      color: var(--rt-orange-2);
      font-size: 13px;
      font-weight: 900;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .rtp-eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: var(--rt-orange);
      box-shadow: 0 0 18px rgba(240, 154, 55, 0.9);
      flex: 0 0 auto;
    }

    .rtp-btn {
      position: relative;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      min-height: 52px;
      padding: 15px 22px;
      border-radius: 999px;
      font-weight: 900;
      overflow: hidden;
      text-align: center;
      transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease, border-color 0.25s ease;
    }

    .rtp-btn::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(100deg, transparent 0%, rgba(255, 255, 255, 0.28) 45%, transparent 70%);
      transform: translateX(-120%);
      transition: transform 0.7s ease;
      pointer-events: none;
    }

    .rtp-btn:hover::after {
      transform: translateX(120%);
    }

    .rtp-btn:hover {
      transform: translateY(-3px);
    }

    .rtp-btn.primary {
      color: #071423;
      background: linear-gradient(135deg, var(--rt-orange), var(--rt-orange-2));
      box-shadow: 0 16px 42px rgba(240, 154, 55, 0.26);
    }

    .rtp-btn.secondary {
      color: var(--rt-white);
      border: 1px solid rgba(255, 255, 255, 0.16);
      background: rgba(255, 255, 255, 0.06);
      backdrop-filter: blur(14px);
    }

    .rtp-hero {
      position: relative;
      min-height: 720px;
      padding: 76px 0 88px;
      overflow: hidden;
      isolation: isolate;
      background:
        radial-gradient(circle at 84% 16%, rgba(240, 154, 55, 0.18), transparent 24%),
        radial-gradient(circle at 16% 22%, rgba(255, 255, 255, 0.055), transparent 28%),
        linear-gradient(135deg, #04111d 0%, #07192b 58%, #091c2f 100%);
    }

    .rtp-hero::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
      background-size: 42px 42px;
      mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.72), transparent);
      z-index: -2;
    }

    .rtp-hero::after {
      content: "";
      position: absolute;
      inset: auto -10% -26% -10%;
      height: 360px;
      background: radial-gradient(ellipse at center, rgba(240, 154, 55, 0.13), transparent 64%);
      z-index: -1;
      pointer-events: none;
    }

    .rtp-hero-grid {
      display: grid;
      grid-template-columns: 0.98fr 1.02fr;
      gap: 54px;
      align-items: center;
    }

    .rtp-brand {
      width: 220px;
      max-width: 70%;
      margin-bottom: 28px;
      padding: 14px 18px;
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(12px);
      box-shadow: 0 18px 45px rgba(0, 0, 0, 0.24);
    }

    .rtp-brand img {
      display: block;
      width: 100%;
      height: auto;
    }

    .rtp-hero h1 {
      margin: 20px 0 18px;
      max-width: 760px;
      font-size: clamp(46px, 7vw, 92px);
      line-height: 0.92;
      letter-spacing: -0.07em;
      font-weight: 950;
      color: var(--rt-white);
    }

    .rtp-hero h1 span {
      display: block;
      background: linear-gradient(90deg, var(--rt-orange), var(--rt-orange-2), #ffffff);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .rtp-hero p {
      margin: 0;
      max-width: 660px;
      color: rgba(255, 255, 255, 0.82);
      font-size: clamp(18px, 2vw, 22px);
      line-height: 1.62;
    }

    .rtp-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-top: 30px;
    }

    .rtp-hero-media {
      position: relative;
      min-height: 520px;
      display: grid;
      place-items: center;
      perspective: 1000px;
    }

    .rtp-orbit {
      position: absolute;
      width: 420px;
      height: 420px;
      right: -26px;
      top: -8px;
      border-radius: 999px;
      border: 1px solid rgba(240, 154, 55, 0.16);
      animation: rtpSpin 18s linear infinite;
      pointer-events: none;
      opacity: 0.75;
    }

    .rtp-orbit::before,
    .rtp-orbit::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: var(--rt-orange);
      box-shadow: 0 0 24px rgba(240, 154, 55, 0.75);
    }

    .rtp-orbit::before {
      width: 10px;
      height: 10px;
      top: 36px;
      left: 62px;
    }

    .rtp-orbit::after {
      width: 7px;
      height: 7px;
      right: 56px;
      bottom: 74px;
    }

    .rtp-screen {
      position: relative;
      width: 100%;
      border-radius: 36px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.1);
      box-shadow: 0 30px 90px rgba(0, 0, 0, 0.42), var(--rt-glow);
      animation: rtpFloat 6s ease-in-out infinite;
    }

    .rtp-screen::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(120deg, rgba(240, 154, 55, 0.14), transparent 38%, rgba(255, 255, 255, 0.05));
      z-index: 1;
      pointer-events: none;
    }

    .rtp-screen img {
      display: block;
      width: 100%;
      height: auto;
    }

    .rtp-floating {
      position: absolute;
      left: -18px;
      bottom: 8px;
      width: min(360px, 76%);
      padding: 22px;
      border-radius: 26px;
      background: linear-gradient(180deg, #102844 0%, #0b2036 100%);
      color: var(--rt-text);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: var(--rt-shadow);
      animation: rtpFloatSmall 5s ease-in-out infinite;
    }

    .rtp-floating strong {
      display: block;
      font-size: 38px;
      line-height: 1;
      color: var(--rt-orange);
      letter-spacing: -0.04em;
    }

    .rtp-floating span {
      display: block;
      margin-top: 6px;
      color: var(--rt-muted);
      font-weight: 700;
      line-height: 1.5;
    }

    .rtp-quick {
      margin-top: -52px;
      position: relative;
      z-index: 5;
    }

    .rtp-quick-box {
      display: grid;
      grid-template-columns: 0.78fr 1.22fr;
      gap: 1px;
      border-radius: 30px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.08);
      box-shadow: var(--rt-shadow);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .rtp-quick-main {
      padding: 26px;
      background: linear-gradient(180deg, #132c48 0%, #0d2138 100%);
    }

    .rtp-quick-main strong {
      display: block;
      color: var(--rt-white);
      font-size: 26px;
      letter-spacing: -0.03em;
      line-height: 1.1;
    }

    .rtp-quick-main span {
      display: block;
      margin-top: 8px;
      color: var(--rt-muted);
      line-height: 1.55;
    }

    .rtp-quick-links {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1px;
      background: rgba(255, 255, 255, 0.08);
    }

    .rtp-quick-links a {
      min-height: 130px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 22px;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%);
      transition: background 0.25s ease, transform 0.25s ease;
    }

    .rtp-quick-links a:hover {
      background: linear-gradient(180deg, #173555 0%, #102844 100%);
    }

    .rtp-quick-links b {
      color: var(--rt-white);
      font-size: 18px;
      letter-spacing: -0.02em;
    }

    .rtp-quick-links small {
      color: var(--rt-orange-2);
      font-weight: 900;
    }

    .rtp-stats {
      padding: 34px 0 0;
    }

    .rtp-stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
    }

    .rtp-stat {
      padding: 24px 18px;
      border-radius: 24px;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%);
      text-align: center;
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: 0 16px 42px rgba(0, 0, 0, 0.16);
    }

    .rtp-stat strong {
      display: block;
      font-size: clamp(28px, 3.6vw, 44px);
      line-height: 1;
      color: var(--rt-orange);
      letter-spacing: -0.04em;
    }

    .rtp-stat span {
      display: block;
      margin-top: 10px;
      color: var(--rt-muted);
      font-weight: 800;
      font-size: 13px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .rtp-section {
      padding: 76px 0;
    }

    .rtp-section.soft {
      background:
        radial-gradient(circle at 15% 20%, rgba(240, 154, 55, 0.09), transparent 30%),
        linear-gradient(180deg, var(--rt-bg-2) 0%, var(--rt-bg) 100%);
    }

    .rtp-head {
      display: grid;
      grid-template-columns: 0.8fr 1.2fr;
      gap: 34px;
      align-items: end;
      margin-bottom: 34px;
    }

    .rtp-head h2 {
      margin: 16px 0 0;
      color: var(--rt-white);
      font-size: clamp(34px, 4.5vw, 58px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 950;
    }

    .rtp-head p {
      margin: 0;
      color: #c9d6e6;
      font-size: 18px;
      line-height: 1.68;
    }

    .rtp-software {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
      align-items: stretch;
    }

    .rtp-panel {
      padding: clamp(28px, 4.5vw, 52px);
      border-radius: 34px;
      background: linear-gradient(180deg, var(--rt-card-2) 0%, var(--rt-card) 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: 0 18px 55px rgba(0, 0, 0, 0.22);
    }

    .rtp-panel h2,
    .rtp-panel h3 {
      margin: 0 0 16px;
      color: var(--rt-white);
      font-size: clamp(34px, 4vw, 54px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 950;
    }

    .rtp-panel p {
      margin: 0;
      color: var(--rt-muted);
      font-size: 18px;
      line-height: 1.72;
    }

    .rtp-panel p + p {
      margin-top: 14px;
    }

    .rtp-media-card {
      position: relative;
      min-height: 440px;
      border-radius: 34px;
      overflow: hidden;
      background: #081522;
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: var(--rt-shadow);
    }

    .rtp-media-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      transform: scale(1.02);
    }

    .rtp-media-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(120deg, rgba(240, 154, 55, 0.12), transparent 40%),
        linear-gradient(to top, rgba(4, 17, 29, 0.72), transparent 52%);
      pointer-events: none;
    }

    .rtp-features-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 14px;
    }

    .rtp-feature {
      position: relative;
      min-height: 250px;
      padding: 26px;
      border-radius: 28px;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: 0 16px 45px rgba(0, 0, 0, 0.18);
      overflow: hidden;
      transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
    }

    .rtp-feature::before {
      content: "";
      position: absolute;
      inset: -1px;
      background: linear-gradient(135deg, rgba(240, 154, 55, 0.18), transparent 44%);
      opacity: 0;
      transition: opacity 0.25s ease;
      pointer-events: none;
    }

    .rtp-feature:hover {
      transform: translateY(-5px);
      border-color: rgba(240, 154, 55, 0.28);
      box-shadow: 0 24px 62px rgba(0, 0, 0, 0.28);
    }

    .rtp-feature:hover::before {
      opacity: 1;
    }

    .rtp-icon {
      position: relative;
      z-index: 1;
      width: 48px;
      height: 48px;
      margin-bottom: 18px;
      border-radius: 16px;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, var(--rt-orange), var(--rt-orange-2));
      color: #071423;
      font-size: 22px;
      font-weight: 950;
      box-shadow: 0 16px 34px rgba(240, 154, 55, 0.22);
    }

    .rtp-feature h3 {
      position: relative;
      z-index: 1;
      margin: 0 0 10px;
      color: #ffffff;
      font-size: 22px;
      line-height: 1.08;
      letter-spacing: -0.035em;
      font-weight: 950;
    }

    .rtp-feature p {
      position: relative;
      z-index: 1;
      margin: 0;
      color: #c9d6e6;
      line-height: 1.62;
      font-weight: 650;
    }

    .rtp-tabs-shell {
      display: grid;
      grid-template-columns: 330px 1fr;
      gap: 22px;
      align-items: stretch;
    }

    .rtp-tabs-nav {
      display: grid;
      gap: 14px;
      align-content: start;
    }

    .rtp-tab-btn {
      width: 100%;
      border: 1px solid rgba(255, 255, 255, 0.11) !important;
      border-radius: 22px;
      padding: 18px;
      cursor: pointer;
      text-align: left;
      background: linear-gradient(180deg, #10243b 0%, #0b1d30 100%) !important;
      color: #ffffff !important;
      font-family: inherit;
      box-shadow: 0 14px 34px rgba(0, 0, 0, 0.22) !important;
      transition: transform 0.25s ease, border-color 0.25s ease, background 0.25s ease, box-shadow 0.25s ease;
    }

    .rtp-tab-btn:hover {
      transform: translateX(6px);
      border-color: rgba(240, 154, 55, 0.36) !important;
      background: linear-gradient(180deg, #173555 0%, #102844 100%) !important;
    }

    .rtp-tab-btn.active {
      transform: translateX(6px);
      border-color: rgba(255, 182, 92, 0.8) !important;
      background: linear-gradient(135deg, #f09a37 0%, #ffb65c 100%) !important;
      color: #071423 !important;
      box-shadow: 0 18px 42px rgba(240, 154, 55, 0.28) !important;
    }

    .rtp-tab-btn strong {
      display: block;
      color: #ffffff !important;
      font-size: 20px;
      line-height: 1.1;
      letter-spacing: -0.03em;
      font-weight: 950 !important;
    }

    .rtp-tab-btn span {
      display: block;
      color: #b8c6d8 !important;
      margin-top: 6px;
      font-size: 14px;
      line-height: 1.45;
      font-weight: 700 !important;
    }

    .rtp-tab-btn.active strong,
    .rtp-tab-btn.active span {
      color: #071423 !important;
    }

    .rtp-tab-panel {
      display: none;
      min-height: 520px;
      overflow: hidden;
      border-radius: 34px;
      background: linear-gradient(180deg, var(--rt-card-2) 0%, var(--rt-card) 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: var(--rt-shadow);
    }

    .rtp-tab-panel.active {
      display: grid;
      grid-template-columns: 1fr 1fr;
      animation: rtpFade 0.45s ease both;
    }

    .rtp-tab-media {
      min-height: 520px;
      background: #081522;
      overflow: hidden;
    }

    .rtp-tab-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      transform: scale(1.02);
    }

    .rtp-tab-content {
      padding: clamp(30px, 5vw, 52px);
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .rtp-tab-content h3 {
      margin: 0 0 14px;
      color: #ffffff !important;
      font-size: clamp(32px, 4vw, 52px);
      line-height: 1;
      letter-spacing: -0.05em;
      font-weight: 950;
      text-shadow: 0 2px 18px rgba(0, 0, 0, 0.28);
    }

    .rtp-tab-content p {
      margin: 0;
      color: #c9d6e6 !important;
      font-size: 18px;
      line-height: 1.7;
    }

    .rtp-checks {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
      margin: 24px 0 0;
      padding: 0;
      list-style: none;
    }

    .rtp-checks li {
      position: relative;
      padding: 14px 16px 14px 48px;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.065) !important;
      color: #f4f8fc !important;
      font-weight: 800 !important;
      border: 1px solid rgba(255, 255, 255, 0.09) !important;
      word-break: normal !important;
      overflow-wrap: normal !important;
      hyphens: none !important;
      line-height: 1.45;
    }

    .rtp-checks li::before {
      content: "✓";
      position: absolute;
      left: 16px;
      top: 13px;
      width: 24px;
      height: 24px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, #f09a37, #ffb65c) !important;
      color: #071423 !important;
      font-size: 14px;
      font-weight: 950;
    }

    .rtp-audience-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }

    .rtp-audience {
      position: relative;
      min-height: 250px;
      padding: 28px;
      border-radius: 30px;
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(14px);
      overflow: hidden;
      transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
    }

    .rtp-audience::before {
      content: "";
      position: absolute;
      inset: -1px;
      background: linear-gradient(135deg, rgba(240, 154, 55, 0.18), transparent 42%);
      opacity: 0;
      transition: opacity 0.25s ease;
      pointer-events: none;
    }

    .rtp-audience:hover {
      transform: translateY(-5px);
      border-color: rgba(240, 154, 55, 0.26);
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.22);
    }

    .rtp-audience:hover::before {
      opacity: 1;
    }

    .rtp-audience h3,
    .rtp-audience p,
    .rtp-audience .rtp-icon {
      position: relative;
      z-index: 1;
    }

    .rtp-audience h3 {
      margin: 0 0 12px;
      color: #ffffff;
      font-size: 25px;
      line-height: 1.12;
      letter-spacing: -0.035em;
      font-weight: 950;
    }

    .rtp-audience p {
      margin: 0;
      color: rgba(255, 255, 255, 0.78);
      line-height: 1.65;
      font-weight: 650;
    }

    .rtp-study {
      display: grid;
      grid-template-columns: 0.95fr 1.05fr;
      gap: 24px;
      align-items: stretch;
    }

    .rtp-study-card {
      padding: clamp(28px, 4.5vw, 52px);
      border-radius: 34px;
      background: linear-gradient(180deg, var(--rt-card-2) 0%, var(--rt-card) 100%);
      border: 1px solid rgba(255, 255, 255, 0.08);
      box-shadow: 0 18px 55px rgba(0, 0, 0, 0.22);
